    }).join('') : '';
    const standings = (r.standings || []).map(s => `<div class="standing-row ${s.isPlayer ? 'me' : ''}">
      <span class="sp">${s.pos}</span><span class="nm">${s.name}${s.isPlayer ? ' · you' : ''}</span>
