import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, resolve } from 'node:path';

const root = resolve(process.cwd());
const port = Number(process.env.PORT || 3000);
const mime = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.wasm': 'application/wasm',
  '.glb': 'model/gltf-binary',
  '.mp3': 'audio/mpeg',
  '.ogg': 'audio/ogg'
};

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    let path = resolve(root, '.' + decodeURIComponent(url.pathname));
    if (path !== root && !path.startsWith(root + '/')) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }
    let info = await stat(path).catch(() => null);
    if (info?.isDirectory()) {
      path = join(path, 'index.html');
      info = await stat(path).catch(() => null);
    }
    if (!info?.isFile()) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }
    const body = await readFile(path);
    res.writeHead(200, {
      'Content-Type': mime[extname(path).toLowerCase()] || 'application/octet-stream',
      'Content-Length': body.length,
      'Cache-Control': 'no-cache'
    });
    res.end(body);
  } catch (error) {
    console.error(error);
    res.writeHead(500);
    res.end('Server error');
  }
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Dragon Rush running at http://localhost:${port}`);
});

import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({
  headless: true,
  args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--disable-dev-shm-usage']
});
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => { errors.push('PAGEERROR: ' + e.stack); console.log('PAGEERROR:', e.message); });
page.on('console', (m) => {
  if (m.type() === 'error' || m.type() === 'warning') console.log(m.type().toUpperCase() + ':', m.text());
});
page.on('response', (r) => { if (r.status() >= 400) console.log('HTTP', r.status(), r.url()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(3500);
console.log('boot done?', await page.locator('#boot').count());
console.log('menu buttons:', await page.locator('#screen button').count());
console.log('screen text:', (await page.locator('#screen').innerText()).slice(0, 400));
console.log('mode:', await page.evaluate(() => window.dragonGame?.mode));
console.log('fps:', await page.evaluate(() => window.dragonGame?.fps));
await page.screenshot({ path: 'screenshots/menu-mobile.png', fullPage: false, type: 'jpeg', quality: 72 });
const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
desktop.on('pageerror', (e) => { errors.push('DESKTOP PAGEERROR: ' + e.stack); console.log('DESKTOP PAGEERROR:', e.message); });
await desktop.goto('http://localhost:3000/', { waitUntil: 'load' });
await desktop.waitForTimeout(3500);
await desktop.screenshot({ path: 'screenshots/menu-desktop.jpg', fullPage: false, type: 'jpeg', quality: 72 });
console.log('errors:', errors.length);
await browser.close();

