Index: src/styles.css
===================================================================
--- src/styles.css
+++ src/styles.css
@@ -614,9 +614,9 @@
 @keyframes toastIn { from { opacity: 0; transform: translateY(-10px); } }
 @keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

 /* ── results ────────────────────────────────────────────────────────────── */
-.results-wrap { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 20px; background: radial-gradient(ellipse at 50% 30%, rgba(30,60,72,.55), rgba(2,8,12,.88)); backdrop-filter: blur(6px); animation: fadeIn .3s ease; overflow-y: auto; }
+.results-wrap { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 20px; background: radial-gradient(ellipse at 50% 30%, rgba(30,60,72,.55), rgba(2,8,12,.88)); backdrop-filter: blur(6px); animation: fadeIn .3s ease; overflow-y: auto; pointer-events: auto; }
 .results { width: min(680px, 95vw); max-height: 94dvh; overflow-y: auto; border-radius: 24px; border: 1px solid var(--line); background: linear-gradient(170deg, rgba(13,36,47,.97), rgba(5,16,23,.98)); box-shadow: 0 40px 100px rgba(0,0,0,.7); padding: clamp(18px, 4vw, 32px); position: relative; scrollbar-width: thin; text-align: center; }
 .results::before { content: ''; position: absolute; inset: 0; border-radius: 24px; background: radial-gradient(70% 60% at 50% 0%, rgba(255,209,102,.14), transparent 70%); pointer-events: none; }
 .place-big { font-family: 'Cinzel'; font-size: clamp(52px, 11vw, 92px); line-height: .9; background: linear-gradient(180deg, #fff8e4, #ffd166 60%, #c9852d); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; filter: drop-shadow(0 8px 30px rgba(255,190,80,.3)); position: relative; }
 .place-big.lose { background: linear-gradient(180deg, #e8eef0, #9db4bc); -webkit-background-clip: text; background-clip: text; }

