import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
const errors = [];
async function makePage(viewport) {
  const page = await browser.newPage({ viewport, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message); });
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(2600);
  return page;
}
const page = await makePage({ width: 390, height: 844 });
await page.screenshot({ path: 'screenshots/final-menu-mobile.jpg', type: 'jpeg', quality: 74 });
for (const [nav, name] of [['hangar', 'final-hangar'], ['village', 'final-village'], ['race', 'final-racehub'], ['shop', 'final-shop'], ['explore', 'final-explore']]) {
  await page.locator(`#bottomnav [data-action="goto"][data-id="${nav}"]`).click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 74 });
  console.log(name, await page.evaluate(() => ({ view: window.dragonUI.view, mode: window.dragonGame.mode, topbar: !document.querySelector('#topbar').classList.contains('hidden'), nav: !document.querySelector('#bottomnav').classList.contains('hidden'), scrollH: document.querySelector('#screen').scrollHeight, clientH: document.querySelector('#screen').clientHeight })));
}
// hangar interactions
await page.locator(`#bottomnav [data-action="goto"][data-id="hangar"]`).click();
await page.waitForTimeout(700);
console.log('hangar tabs:', await page.locator('.tabs .tab').count());
await page.locator('.tabs .tab').nth(1).click();
await page.waitForTimeout(400);
console.log('skills visible:', await page.locator('.skill-node').count());
await page.locator('.tabs .tab').nth(2).click();
await page.waitForTimeout(400);
console.log('cosmetics visible:', await page.locator('.swatch').count());
const coinsBefore = await page.evaluate(() => window.dragonUI.S.coins);
const buyBtn = page.locator('.swatch [data-action], .swatch').first();
await page.screenshot({ path: 'screenshots/final-hangar-style.jpg', type: 'jpeg', quality: 74 });
// village build
await page.locator(`#bottomnav [data-action="goto"][data-id="village"]`).click();
await page.waitForTimeout(700);
const build = page.locator('[data-action="build"]').first();
console.log('build buttons:', await page.locator('[data-action="build"]').count());
if (await build.count()) {
  await build.click();
  await page.waitForTimeout(900);
  console.log('after build:', await page.evaluate(() => ({ coins: window.dragonUI.S.coins, village: window.dragonUI.S.village, toast: document.querySelector('.toast')?.innerText || '' })));
}
// landscape race
const land = await makePage({ width: 844, height: 390 });
await land.click('[data-action="quick-race"]');
await land.waitForTimeout(5200);
await land.screenshot({ path: 'screenshots/final-race-landscape.jpg', type: 'jpeg', quality: 74 });
console.log('landscape:', await land.evaluate(() => ({ mode: window.dragonGame.mode, state: window.dragonGame.race?.state, hud: !!document.querySelector('#hud:not(.hidden)'), fps: window.dragonGame.fps })));
await land.evaluate(() => window.dragonUI.pauseRace());
await land.waitForTimeout(500);
await land.screenshot({ path: 'screenshots/final-pause.jpg', type: 'jpeg', quality: 74 });
console.log('pause modal:', await land.locator('.modal-root:not(.hidden)').innerText().catch(() => ''));
console.log('errors', errors.length);
await browser.close();

