  await page.waitForTimeout(1200);
  await page.screenshot({ path: file, type: 'jpeg', quality: 76 });
  console.log(file, await page.evaluate(() => ({ state: window.dragonGame.race.state, speed: Math.round(window.dragonGame.flight.speed), fps: window.dragonGame.fps, pos: window.dragonGame.race.playerPos })));
  await page.close();
}
await shot({ width: 390, height: 844 }, 'screenshots/race-4.jpg');
await shot({ width: 844, height: 390 }, 'screenshots/race-land-4.jpg');
await browser.close();

