import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, hasTouch: true, isMobile: true });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2500);

const runSeries = async (win) => page.evaluate((win) => {
  const ui = window.dragonUI;
  ui.startChampionship('hatchling');
  const c = ui.champ;
  ui.game.pause(true);
  const rivals = ['Vexa', 'Bram', 'Sable', 'Orin', 'Kestrel'];
  const names = win ? [ui.S.riderName, ...rivals] : [...rivals, ui.S.riderName];
  for (let r = 0; r < 3; r++) {
    c.round = r; c.lastProcessed = r - 1;
    ui.processChampionshipResults({
      standings: names.map((n, i) => ({ name: n, isPlayer: n === ui.S.riderName, pos: i + 1 })),
      trackName: 'Hearthfall', mode: 'championship', round: r + 1,
    });
  }
  const fin = ui.finalizeChampionship();
  return {
    champ: fin?.champ, place: fin?.playerPlace,
    league: ui.S.leagues.hatchling,
    coins: ui.S.coins, unlocked: ui.S.unlockedTracks,
  };
}, win);

console.log('lose series:', JSON.stringify(await runSeries(false)));
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2500);
console.log('win series:', JSON.stringify(await runSeries(true)));
await page.evaluate(() => window.dragonUI.renderRaceHub());
await page.waitForTimeout(400);
console.log('skyward enabled:', await page.evaluate(() => {
  const b = document.querySelector('[data-action="pick-league"][data-id="skyward"]');
  return b ? !b.disabled : null;
}));
await page.locator('[data-action="pick-league"][data-id="skyward"]').click();
await page.waitForTimeout(400);
await page.locator('[data-action="enter-champ"]').click();
await page.waitForTimeout(400);
console.log('modal text:', (await page.locator('.modal').innerText()).replace(/\n+/g, ' | ').slice(0, 320));
console.log('errors', errors.length);
await browser.close();

