import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, hasTouch: true, isMobile: true });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE:', m.text()); } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2600);

for (const nav of ['hangar', 'village', 'race', 'shop', 'explore', 'menu']) {
  await page.locator(`#bottomnav [data-action="goto"][data-id="${nav}"]`).click();
  await page.waitForTimeout(650);
  console.log(nav, 'ok', await page.evaluate(() => window.dragonUI.view));
}
await page.locator('#bottomnav [data-action="goto"][data-id="race"]').click();
await page.waitForTimeout(500);
await page.locator('[data-action="start-selected"]').click();
await page.waitForFunction(() => window.dragonGame.race?.state === 'flying', { timeout: 15000 });
console.log('flying');

// joystick drag
const jb = await page.locator('#joystick').boundingBox();
await page.mouse.move(jb.x + jb.width / 2, jb.y + jb.height / 2);
await page.mouse.down();
await page.mouse.move(jb.x + jb.width * 0.85, jb.y + jb.height * 0.5, { steps: 5 });
await page.waitForTimeout(250);
console.log('steer', await page.evaluate(() => ({ x: +window.dragonGame.input.steerX.toFixed(2), y: +window.dragonGame.input.steerY.toFixed(2) })));
await page.mouse.up();
await page.waitForTimeout(200);
console.log('steer released', await page.evaluate(() => window.dragonGame.input.steerX));

// boost hold
const bb = await page.locator('#boost-btn').boundingBox();
await page.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 2);
await page.mouse.down();
await page.waitForTimeout(700);
console.log('boost', await page.evaluate(() => ({ input: window.dragonGame.input.boost, on: document.querySelector('#boost-btn').classList.contains('on') })));
await page.mouse.up();

// ability + manoeuvre cooldown UI
await page.locator('#ability-btn').click();
await page.waitForTimeout(300);
await page.locator('[data-action="use-maneuver"]').click();
await page.waitForTimeout(300);
console.log('cooldowns', await page.evaluate(() => ({
  ability: document.querySelector('#ability-cd').textContent,
  maneuver: document.querySelector('#maneuver-cd').textContent,
  cooling: document.querySelector('[data-action="use-maneuver"]').classList.contains('cooling'),
})));
await page.screenshot({ path: 'screenshots/smoke-race-hud.png' });

// finish and inspect results
await page.evaluate(() => { window.dragonGame.race.state = 'flying'; window.dragonGame.endRace('finish'); });
await page.waitForTimeout(1500);
console.log('results', await page.evaluate(() => ({
  fin: [...document.querySelectorAll('.standing-row')].filter(r => r.textContent.includes('you')).map(r => r.textContent.trim()),
  action: document.querySelector('.results-actions [data-action]')?.dataset.action,
  best: window.dragonUI.S.bestTimes.hearthfall,
})));
await page.screenshot({ path: 'screenshots/smoke-results.png' });

// left-handed toggle persistence
await page.locator('.results-wrap [data-action="goto"][data-id="menu"]').click();
await page.waitForTimeout(800);
await page.locator('#topbar [data-action="settings"]').click();
await page.waitForTimeout(400);
const rows = await page.locator('.opt-row').allInnerTexts();
console.log('settings rows', rows.map(r => r.split('\n')[0]));
await page.locator('[data-action="toggle-setting"][data-id="leftHand"]').click();
await page.waitForTimeout(300);
await page.locator('[data-action="close-modal"]').first().click();
await page.waitForTimeout(400);
console.log('saved leftHand', await page.evaluate(() => window.dragonUI.S.settings.leftHand));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2600);
console.log('persisted', await page.evaluate(() => ({ leftHand: window.dragonUI.S.settings.leftHand, coins: window.dragonUI.S.coins, best: window.dragonUI.S.bestTimes.hearthfall })));

